    const immediate = input.intakeSource === "DIRECT_WAREHOUSE"; const arrived = immediate || Boolean(input.arrivedAt); const inTransit = input.intakeSource === "OWN_PICKUP" && Boolean(input.departedAt) && !arrived;
    const receptionStage = immediate ? "RECEIVING" : arrived ? "ARRIVED" : inTransit ? "IN_TRANSIT" : "PLANNED"; const status = immediate || arrived ? "RECEIVED" : inTransit ? "IN_TRANSIT" : "PLANNED";
    const lot = await tx.customerStorageLot.create({ data: { tenantId: context.tenantId, clientId: client.id, pipelineCaseId: pipelineCase.id, warehouseId: warehouse.id, receptionLocationId: destination.id, authorizationId: authorization.id, lotCode, storageType: input.storageType, intakeSource: input.intakeSource, receptionStage, status, manifestCode: input.manifestCode, expectedUnits: input.expectedUnits ?? (input.items.length || null), groupLeadName: input.groupLeadName, driverName: input.driverName, vehicleCode: input.vehicleCode, sealNumber: input.sealNumber, departedAt: input.departedAt ? new Date(input.departedAt) : null, arrivedAt: arrived ? new Date(input.arrivedAt ?? input.receivedAt) : null, receivedAt: new Date(input.receivedAt), billingStartAt: input.billingStartAt ? new Date(input.billingStartAt) : null, notes: input.notes, nextItemNumber: input.items.length + 1 } });
