    const command = await tx.customerCustodyCommand.create({ data: { tenantId: context.tenantId, requestId: input.requestId, operation: input.operation, payloadHash: input.payloadHash, targetRef: lot.storageRef, resultJson: {}, ...actor(context) } });
    const created = [];
    for (const item of input.items) {
      const inspectionStatus = input.intakeSource === "OWN_PICKUP" ? "PREVERIFIED" : input.storageType === "IMPORT_STORAGE" ? "VISUAL_REQUIRED" : "FULL_REQUIRED";
      const row = await tx.customerStoredItem.create({ data: { tenantId: context.tenantId, storageLotId: lot.id, currentLocationId: immediate ? destination.id : null, inventoryNumber: item.position, itemCode: `${lotCode}-${String(item.position).padStart(3, "0")}`, externalCode: item.externalCode, description: item.description, category: item.category, quantity: item.quantity, unit: item.unit, volumeM3: item.volumeM3, weightKg: item.weightKg, condition: item.condition, evidence: item.evidence === null ? Prisma.DbNull : item.evidence, notes: item.notes, inspectionStatus, status: immediate ? "IN_CUSTODY" : "EXPECTED", receivedAt: immediate ? new Date(input.receivedAt) : null } }); created.push(row);
      if (immediate) await tx.customerCustodyMovement.create({ data: { tenantId: context.tenantId, storageLotId: lot.id, storedItemId: row.id, commandId: command.id, destinationLocationId: destination.id, movementType: "RECEIVE", quantity: item.quantity, occurredAt: new Date(input.receivedAt), ...actor(context) } });
    }
