    const item = ["SCAN_ITEM", "PUT_AWAY_SCAN"].includes(input.action) ? lot.items.find((row) => row.itemCode === input.scanCode || row.externalCode === input.scanCode) : input.itemRef ? lot.items.find((row) => row.itemRef === input.itemRef) : null;
