    if (["SCAN_ITEM", "RECORD_CONDITION", "DESCRIBE_ITEM", "CONFIRM_INSPECTION", "PUT_AWAY_SCAN", "REPORT_EXCEPTION", "RESOLVE_EXCEPTION"].includes(input.action) && !item) custodyFail("CUSTOMER_CUSTODY_RESOURCE_NOT_FOUND", 404);
