    if (!allowedStages[input.action]?.includes(lot.receptionStage)) custodyFail("CUSTOMER_CUSTODY_RECEPTION_TRANSITION_INVALID", 409);
    if (input.action === "SCAN_ITEM" && item.status !== "EXPECTED") custodyFail("CUSTOMER_CUSTODY_ITEM_ALREADY_RECEIVED", 409);
    if (input.action === "PUT_AWAY_SCAN" && (item.status !== "IN_CUSTODY" || !["CLEARED", "PREVERIFIED"].includes(item.inspectionStatus) || OCCUPANCY_BLOCKED.has(targetLocation.custodyOccupancyState?.status))) custodyFail("CUSTOMER_CUSTODY_RECEPTION_TRANSITION_INVALID", 409);
    if (input.action === "CONFIRM_INSPECTION" && !["VISUAL_REQUIRED", "FULL_REQUIRED", "HOLD"].includes(item.inspectionStatus)) custodyFail("CUSTOMER_CUSTODY_RECEPTION_TRANSITION_INVALID", 409);
    if (input.action === "REPORT_EXCEPTION" && item.status === "RELEASED") custodyFail("CUSTOMER_CUSTODY_RECEPTION_TRANSITION_INVALID", 409);
    if (input.action === "RESOLVE_EXCEPTION" && item.status !== "HOLD") custodyFail("CUSTOMER_CUSTODY_RECEPTION_TRANSITION_INVALID", 409);
    if (input.action === "RECORD_CONDITION" && item.status !== "IN_CUSTODY") custodyFail("CUSTOMER_CUSTODY_RECEPTION_TRANSITION_INVALID", 409);
    if (input.action === "DESCRIBE_ITEM" && item.status !== "IN_CUSTODY") custodyFail("CUSTOMER_CUSTODY_RECEPTION_TRANSITION_INVALID", 409);
    if (input.action === "DESCRIBE_ITEM" && !packageForm) custodyFail("CUSTOMER_CUSTODY_RESOURCE_NOT_FOUND", 404);
    if (input.action === "DESCRIBE_ITEM" && item.identitySource === "GENERATED_AT_RECEPTION" && (!Array.isArray(item.evidence) || !item.evidence.some((entry) => typeof entry === "string" && (entry.startsWith("COND|") || entry.startsWith("OBS|"))))) custodyFail("CUSTOMER_CUSTODY_CONDITION_REQUIRED", 409);
